INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1374832-pe101', 'stk-medoalkebsi', 'PE 101', 'info', '{"desc": "وعليكم السلام ورحمه الله وبركاته.\n\nفي عندك 4 لعبات.\nBadminton\nهذي اللعبه الي هي الريشه \" زي التنس\"\nFootball\nكره القدم غنيه عن التعريف , بس الاحظ الشعب كله مايمدحها لان الدكاتره يبغون شخص حريف والله اعلم\nBasketball\nكره سله كمان غنيه عن التعريف , واشوفها صعبه\nJudo\nالجودو حاجه وناسه , لكن الدكتور حقها مره كريف ولا يعطي درجات\n\nانا انصحك بالريشه , مع الدكتور معتز حسنين , لان الكتور يتعامل معك كأب واخ اكبر وكمان يدف دف مو صاحي .\nوالعبه سهله , انا اخذتها في 101 ما كنت اعررف حتى ارسل ,بس تعلمت لها.\n\nاما بالنسبه للاوبيس , اتوقع في لهم سكاشن خاصه للوزن واشياء كذا , اتذكر اذا شاوفوآ شخص سمين يقولوله ايش راك تسجل في سكشن مدري ايش الساعه مدري كم عشان اظن يساعد تخفف وزن وزي كذا … والله اعلم\nوبما انك ابويس , افضل شي تختاره الريشه …\nوبالتوفيق … 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pe-101/162007/4", "user": "Medoalkebsi", "ts": 1401511502000, "tid": 162007, "pn": 4}}', 1401511502000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p938201-pe101', 'stk-the_marvel', 'PE 101', 'info', '{"desc": "it’s not a big deal\n\nتراها مادة حضور…أنت طالب منتب لاعب…\n\nمطلوب منك تحضر وتسوي أي شي وتطلع…\n\nأقل شي تآخذ بي بلس مع الحضور…بي كان المدرس سيء\n\nعطيتك المينموم…مع الحضور المفروض اي\n\nيعني مثلا بتآخذ سي وأنت تحضر !\n\nمستحيل…مادة سعة صدر…وتراها ساعة…نزلها ولا تشيل همها\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pe101/115716/2", "user": "The_Marvel", "ts": 1322406551000, "tid": 115716, "pn": 2}}', 1322406551000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p722513-pe101', 'stk-omar.a', 'PE 101', 'info', '{"desc": "اختبرت اليوم الساعة 12:00 Pm في مبنى 11\n\nالاختبار بشكل عام : متوسط الى سهل مع شوية لفات في الاسئلة\n\nوفي حاجات من بين السطور يعني اللي مومذاكر كويس مستحيل يتذكرها 😦\n\n10 اسئلة True or False\n\n5 Multiple choice questions - 2 points for each question\n\nCPR مو مركزين عليه بقد ما هم مركزين على Diabetes & cholesterol & Hypertension\n\nمدة الاختبار : 15 دقيقة … تكتب اسمك والآيدي حقك … والسكشن نمبر\n\nبعد ما تخلص تسلم الورقة وترجع الكرسي من المكان اللي جبته 😆\n\nهذا كل ما اعرفه عن\n\nPe 101 health education test\n\nالدكتور اسمه : ادوالي اديجومو …\n\nوعندك كمان الدكتور : حبيب الربعان …", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pe101/96767/11", "user": "Omar.a", "ts": 1287261947000, "tid": 96767, "pn": 11}}', 1287261947000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p720095-pe101', 'stk-ca2oom', 'PE 101', 'info', '{"desc": "ترى مرى سهالات الاختبار\nويختلف من مدرس للثاني …\nاما صح او خطا … او اختيارات\nانا عند داوود … و كان برضه معنا سكشن جسور و كان الاختبار سهالات صح و خطا\nبحاول اعطيك كم سؤال من الي افتكرهم …\nو طبعا ذاكر الكتاب كلها كم صفحة … مابتاخذ منك نص ساعة\n\n- الكولسترول نوعين\nLDL & HDL\nLDL = more fat and less protein\nHDL = More protein and less fat\n\n- مريض السكر يبتعد عن السكريات و الحلويات بانواعها\n\n- التمارين تفيد الجسم و تقلل من اصابة ارتفاع ضغط الدم\n\n- انواع مرض ضغط الدم … نوعين\nبصفة عامة ترى جاب عدد انواع كل مرض … فـ ركز عليهم\n\n…", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pe-101/96483/8", "user": "Ca2oom", "ts": 1286867573000, "tid": 96483, "pn": 8}}', 1286867573000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1451274-pe101', 'stk-al-houri', 'PE 101', 'info', '{"desc": "انا درست عند الدكتور حبيب الربعان 151\nالدكتور مرة ممتاز وبتستفيد معه حتى لو ما تعرف تلعب سلة واشوفه يعطي المادة حقها ويحاول يدرب الطلاب ويعطيهم معلومات عن قوانين اللعبة\nاما الاختبارات في اختبارين تحريرين (واحد بعد القسم النظري في المادة ويكون عن مواضيع الكتاب - والثاني بعد القسم العملي في المادة ويكون عن السلة) واختبار نهائي عملي مثل ما قال الاخ بروتوكول\nالدكتور يعطي بونصات (واحد على تقرير تكتبه في موضوع من المواضيع اللي يعطيك اياها - والثاني عن افضل تمريرة - والثالث لحضور دوري كرة السلة)\nفاذا انت ناوي تستفيد في مهاراتك الرياضية وتتعلم لعبة جديدة سجل عنده\nانا اعتبره افضل مدرسي الرياضة اللي درسوني طوال عمري", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pe-101-in-153/173569/7", "user": "Al-Houri", "ts": 1465227224000, "tid": 173569, "pn": 7}}', 1465227224000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1075457-pe101', 'stk-faisal_2011', 'PE 101', 'info', '{"desc": "السنة التحضيرية\n\nPE 001\nPE 002\nهناك كتاب طبعا تقريبا ٣٠ صفحة\nتدرسه اول ٥ اسابيع وتختبر \" كويز \" فيه بعدين تبدا بالكورسات\nالكورسات حسب المدرس\nبس اتوقع في PE002 فيه كورس سباحة لاغلب المدرسين 😆\n\n-----\nالجبل\n\nPE 101 . 102 . 201 . 202\n\nفي الجبل غالبا حسب تخصصك ! الهندسة اتوقع بس بيدرسون 101 , 102\nيعني كورسين بس\nو وقت التسجيل تعرف المدرس وش بيدرسك \" طائرة،قدم،ريشة،لياقة،سلة…\"\n\nوطبعا فيه كتاب و اختبار \" كويز \"", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/129637/3", "user": "Faisal_2011", "ts": 1344038583000, "tid": 129637, "pn": 3}}', 1344038583000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p622821-pe101', 'stk-anoosh', 'PE 101', 'srcU', '{"html": "^^^<br><br>مدري اذا تقصد 2003<br><br>​<span data-fid=\"stk-f622821-0\" class=\"src-fchip\" contenteditable=\"false\"></span>​", "files": {"stk-f622821-0": {"name": "Basketball-word 2003.doc", "v": "data:application/msword;base64,"}}, "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pe101/89372/9", "user": "Anoosh", "ts": 1275752167000, "tid": 89372, "pn": 9}}', 1275752167000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11372-pe101', 'stk-user11372', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f68323", "n": "Dr. A.a. Ibeid", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 - TERM 201 ترم الكورونا اونلاين\n\nالتحضير : بداية كل كلاس يحضر عن طريق الاسماء\n\nطريقة الشرح : بداية الفصل كان يشرح الكتاب طريقة شرح ممتعة مرررره يعامل الطلاب ابناااااااااااااااااااااااء والله دكتور كلمة اسطورة قليلة فيه حقه\n\nالكويزات : ما اختبرنا كويزات فقط طلب منا 3 مرات عروض بوربوينت للتقييم ماتتجاوز 4 شرائح لكل واحد وسهلة جدا\n\nالمياجر: مافي\n\nالفاينلات : مافي\n\nالقريد النهائي: A++++++++++++++++++++++++++++++++++++++++++\n\nالصوت: واضح\n\nإضافات : سواء كنت بالاوريا او بالجبل الدكتور اسطورة اسطورة اسطورة\nولو قدرت تلحق عليه اسجد لربك ليل نهار لانه اسطورة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527890-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-a-ibeid/68323/42", "user": "user11372", "ts": 1610701821000, "tid": 68323, "pn": 42}}]}', 1610701821000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-llabdulmalikll-pe101', 'stk-llabdulmalikll', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f68326", "n": "Dr. M.h. Hamdan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 - 151\n\n- التحضير : ببداية المحاضرة غالباً , يقبل الـMake Up .\n\n- طريقة الشرح : ما كان فيه شرح تقريباً , كتب الـPE عموماً تعطيك معلومات عامة في الصحة و اللياقة , فالدكتور قسَّم الطلاب إلى مجموعات كل وحده منهم مسؤولة عن تقديم عرض لموضوعها و العرض الأفضل يكون له Bonus .\n\n- الـQuizzes : كان فيه واحد بس عن كامل المحتوى إلِّي في الكتاب , عطانا ورقة قبل أسبوعين من الـQuiz فيها 30 عبارة تقريباً و الـQuiz عبارة عن 10 فقرات صح و خطأ من الـ30 عبارة إلِّي في الورقة .\n\n- الصوت : واضح , يتكلم غالباً بالعربي و قليل جداً بالإنقليزي .\n\n- الـGrade : أخذت +A .\n\n- إضافات : بأخر الفصل يكون فيه طريقتين لـBonus زيادة , وحده منها تعبِّي نتايج الاستبيان إلِّي هو يسويه في بحثه و الثانية هي عن بحث في موضوع من اختيار الدكتور , أخذت معه الـBadminton و استمتعت فيها الصراحة , لو أقدر أنزِّلها مرة ثانية بأنزِّلها .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438196-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-h-hamdan/68326/92", "user": "llABDULMALIKll", "ts": 1452117706000, "tid": 68326, "pn": 92}}]}', 1452117706000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mulla-pe101', 'stk-mulla', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f68326", "n": "Dr. M.h. Hamdan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Term 171 Pe101-Badminton\n\nالتحضير :\nفي العادة بعد ما يبدأ وقت الكلاس ب خمس دقايق ويسمح انك تحضر في سكشن غير سكشنك بشرط تستمر هناك.\nولو كان عندك ظرف بيتفهم ويسمح لك تحضر في سكشن ثاني.\nطريقة الشرح :\nيشرح لك المهارات والقوانين + كان سوا قروب واتساب وارسل لنا ملف بالاشياء المهمة.\nالكويزات :\nاحلى ما يكون يعطيك ورقة فيها حول 30 عبارة صح وغلط يجيب لك 10 منهم بالاختبار.\nالمياجر:\nلا يوجد.\nالفاينلات :\nلايوجد.\nالقريد النهائي:\nA\nالصوت:\nواضح بس انجليزيته شوية تعبانه.\nإضافات :\nدكتور ممتاز ومتعاون وعنده بحث يعطيك عليه بونص 5 درجات. انصح انك تسجل عنده وبقوة بعد.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1486915-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-h-hamdan/68326/97", "user": "Mulla", "ts": 1517200359000, "tid": 68326, "pn": 97}}]}', 1517200359000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-r.y-pe101', 'stk-r.y', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f68326", "n": "Dr. M.h. Hamdan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Pe 101 Term 181\nاسطوووورة وودي لو ان كل المدرسين مثله عسل وحبييب وطييب مره وواضح في كل شي بس الطلاب الي يخربونها معه ومن ناحية كرف هو يسوي شغله المطلوب منه يعني لاتستغرب انه يكرف طبيعي تراك في كلاس رياضه وتمنيت انزل عنده 102 بس للاسف مانزل هو .\nاقل ما يقال عنه انه بمثابة الاخ الاكبر الله يطول بعمره\nاييه صح وعنده غياب مجاني بعد .\nالقريد النهائي A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1506455-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-h-hamdan/68326/99", "user": "R.Y", "ts": 1551032053000, "tid": 68326, "pn": 99}}]}', 1551032053000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulmalik123-pe101', 'stk-abdulmalik123', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f68326", "n": "Dr. M.h. Hamdan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101-192\nاسوء دكتور ممكن تاخذ معاه الكورس جد الدكتور سيء بداية الترم كان طيب و كلامه معسول و يقلك ما عليك ولا تخاف وقريداتكم حتكون طيب وحتكون بين ال+B وال+A والي ما يغيب اعطيه +A بس والله انه كذاب القريدات كلها سيئة وطايحة ندمان اني اخذت معاه الكورس.\nالتقييم F ولو في اسوء اعطيته", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1520793-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-h-hamdan/68326/101", "user": "abdulmalik123", "ts": 1584283155000, "tid": 68326, "pn": 101}}]}', 1584283155000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-pe101', 'stk-mohammed_mag', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f68326", "n": "Dr. M.h. Hamdan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : محمد الحمدان\nالمادة: PE 101 ( عن بعد اونلاين )\nالفصل الدراسي: 201\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : جدا جدا متساهل , ما اذكر انه حضر الا 5 مرات بالترم كله , حتى لو غبت في الخمس مرات هذي يمكن يسامحك عنها اذا وضحتله ظروفك\n\nطريقة الشرح : يشرح بطريقه حلوه وفعاله , لكن أغلب الترم كان شرح الطلاب يعني عروض بأدوار ومجموعات\n\nالكويزات : من اسهل الكويزات الي ماتشيل همها , يعطيك ورقه تحفظها , والكويز مرح يخرج عن الورقه\n\nالمياجر: لا يوجد\n\nالفاينلات : لا يوجد\n\nالقريد النهائي: A+\n\nالصوت: واضح جدا\n\nإضافات : الدكتور هذا من افضل الدكاتره الي يمكن يمر عليك ويريحك من ناحيه الضغوطات .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527523-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-h-hamdan/68326/103", "user": "Mohammed_Mag", "ts": 1609690733000, "tid": 68326, "pn": 103}}]}', 1609690733000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-yousef_alamoudi_4507-pe101', 'stk-yousef_alamoudi_4507', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f68326", "n": "Dr. M.h. Hamdan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE101- term 201\n\nالتحضير : جدا متساهل حضر مرات قليلة في الترم و كان يسامح في الغيابات شوي.\n\nطريقة الشرح : يشرح شرح واضح و ما فيه اشكالية، بس الترم كان في جزء للطلاب يسووه اللي هي العروض فما كان يشرح في ذيك الفترة.\n\nالكويزات : جداااا سهلة، بكل بساطة ورقة يعطيك اياها احفظها زي اسمك و انتهى و ابشر بالدرجة.\n\nالميد و المياجر و الفاينل : لا يوجد\n\nالقريد النهائي : A+ قليلة بحقه.\n\nالصوت: واضح ما يحتاج\n\nاضافات: الدكتور جددداااا حبوب و متفاهم و متعاون، و احلى شئ انه يحب يخلص الكلاس سريع سريع… حرفيا الكلاس عنده نص ساعة و سلام (ما يزيد الا اذا الوضع يحتاج)، يبغى يحسسك انك منت منزل المادة، انصح بيه و بقوة و انت مغمض نزل عنده، نصيحة انتبه للغيابات حاول انك ما تغيب بقد ما تقدر لانه كل غياب بدريجتين!، و العروض امورها سهالات معاه ما عليك.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527782-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-h-hamdan/68326/104", "user": "yousef_Alamoudi_4507", "ts": 1610299465000, "tid": 68326, "pn": 104}}]}', 1610299465000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-faisal.kfupm-pe101', 'stk-faisal.kfupm', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f68326", "n": "Dr. M.h. Hamdan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE101 TERM211\nالتحضير : بداية الكلاس ويسمح بالميك اب\nطريقة الشرح : يجلس ويتكلم ولا انت فاهم وش يبي\nالكويزات : صعبة\nالفاينلات : ظالم لابعد حد ويطلبك اشياء تعجيزية\nالقريد النهائي: F\nالصوت: واضح\nإضافات : لا تنزل معه ابد بداية الترم يقولك كلام معسول ولا تخافون ومن هالكلام ونهاية الترم يخسف فيك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533281-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-h-hamdan/68326/105", "user": "Faisal.kfupm", "ts": 1641241153000, "tid": 68326, "pn": 105}}]}', 1641241153000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-a77-pe101', 'stk-a77', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f68326", "n": "Dr. M.h. Hamdan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Pe101 term241 squash\nطريقة الشرح : كل بداية كلاس ينزل يشرح لك الأساسيات فخمس دقايق ويخليك تدرب لحالك باقي الحصة\nالكويزات : عطانا كويز عليه ٢٠ درجة وعطى الكل فل فيه على كلامه\nالمياجر:\nالفاينلات :\nالقريد النهائي:c\nالصوت: واضح\nإضافات : العيب الوحيد اللي في الدكتور اخلاقه اللي مش ولا بد و انه شايف روحه على الطلاب كذا موقف شفته بعيوني إذا جة طالب يبغا ميك أب يقوله اطلع برا لا تكلمني بدل لا يفهمه باحترام وحصل لي موقف معاه وقام يصارخ عليي ويقول أنت ماتفهم و و و", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1538420-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/m-h-hamdan/68326/106", "user": "A77", "ts": 1733922487069, "tid": 68326, "pn": 106}}]}', 1733922487069, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user2316-pe101', 'stk-user2316', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f68330", "n": "Dr. Mootaz Hasanain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أنا اخذت معاه pe 101 و 102\n\nالتحضير : كل كلاس بعدها بخمس دقائق يحضر… بعض المرات حتى لو تأخرت ما يقول شي… لك عدد محدود من الميك ابز ((السمستر هذا 2 لكل لعبة))\nطريقة الشرح :يشرح اللعبة بالتدريج ويجزأها على الكلاسات المطلوبه منه ويخليك تلعب عشان تتقن المهارة اللي شرحها\nالكويزات : يطلب منك بحث في منتصف الفصل… عن موضوع يحدده… يقسم الطلاب لمجموعات ويختاروا موضوع ويسلموه على سي دي… والبحث ما يحتاج له تعب مجرد انك تدخل قوقل وتدور\nالمياجر:لكل لعبة لها اختبار فاينل … يعني بيكون متوسط… يشرحها الجمل بالعربي للمساعدة\nالقريد النهائي:+A لل 101 و من b+ الى A لل 102\nالصوت:ممتاز\nإضافات :السمستر هذا كان فيه تعقيد في القريدات لكن جزاه الله خير اعطاني القريد اللي ابغاه\nلكن هو بيحترمك كثير اذا ما غبت عنده\nمع العلم اني نزلت البي اي 3 مرات 71 و 72 و 73 وكلها حذفتها وارتحت مع الدكتور معتز واخذتهم ورا بعض 81 و 82", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p425287-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mootaz-hasanain/68330/15", "user": "user2316", "ts": 1246636257000, "tid": 68330, "pn": 15}}]}', 1246636257000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdulla_yahia-pe101', 'stk-abdulla_yahia', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f68330", "n": "Dr. Mootaz Hasanain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "د. معتز حسنين ]\n\nPE 101 : Badminton - Term 141\n- التحضير : دايماً - ينادي بالرقم التسلسلي بداية الكلاس + ما يدقق في التأخير …\n\n- طريقة الشرح : شرحه واضح و جيد …\n\n- الكويزات : أعطانا كويزين سهلين ( صح و خطأ ) واحد على المنهج و الثاني على الريشة …\n\n- المياجر : ___ …\n\n- الفاينلات : ___ …\n\n- القريد النهائي : A\n\n- الصوت : واضح و سلس + حماسي إلى حد ما …\n\n- إضافات : الدكتور محترم و بشوش + يحب يمزح مع الطلاب + يدف دف بسيط في القريدات …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1422457-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mootaz-hasanain/68330/41", "user": "Abdulla_Yahia", "ts": 1422285357000, "tid": 68330, "pn": 41}}]}', 1422285357000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-student_nz-pe101', 'stk-student_nz', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70305", "n": "أ. يحيى داوود", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "طيب الكلاس كان ممتع وقصير جدا\n\npe101\n\nالمهم الرجال يكرف\nو الاختبارات اهم شي\nوكمان الحظور\n\nالمهم\n\nتعبت معاه و اعطاني بي\n\nصراحة يعني كنت اتوقع a+\n\nلكن الحمد لله على كل حال\nاذا انحديت معاه الله يعينك لكن اتوقع في غيره احسن 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p641166-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/70305/17", "user": "student_NZ", "ts": 1277134648000, "tid": 70305, "pn": 17}}]}', 1277134648000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-chelsea_17-pe101', 'stk-chelsea_17', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70305", "n": "أ. يحيى داوود", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 - Term 132\n\nالتحضير :\nبداية الكلاس لكن ما يحاسب واجد عالتأخير لكن لا تزودها.\n\nطريقة الشرح :\nقبل كل مهارة يشرح لكم كيف تطبقونها بشكل عملي\n\nالكويزات :\nكويز سهل ويحدد لكم من الكتاب.\n\nالمياجر:\nالفاينلات :\n\nالقريد النهائي:\nA\n\nالصوت:\nواضح ونادر يتكلم انجليزي\n\nإضافات :\nالدكتور طيب بتعامله مع الطالب ويقدر الظروف يعني لو كان عندك ميجر وكنت مضيع ما ذاكرت قل له وبيطلعك اذا ما كان في اختبار أو شيئ مهم , لكن ترى كلاسه كرف بالعاده لكن احنا كنا تقريبا سكشنين بسكشن واحد ( عددنا كبير ) فكان الوضع أخف لأنه يخليكم تلعبون الى نهاية الكلاس.\n\nفريقنا فاز بالبطوله وقال بعطي كل واحد +5 بونوس لكن ما فادتنا أبدا لأن نظامه بالقريدات كالتالي :\n\nيشوف أعلى طالب بالكلاس كم جاب ويبدأ الـ A+ من عنده لكن المشكلة ان درجة البونوس يحسبها قبل ما يثبت القريد فما تستفيدون من البونوس , واذا قال لكم احضروا مباراة البطوله عشان البونوس لا تتعبون نفسكم احنا قال لنا بشكل مازح بعد البطولة أنتم جيتم غصب عن شواربكم .\n\nممكن بنهاية السمستر يعطيك مجموع نازل لكن عشان نظام توزيعه للقريدات لا تخاف , مثلا أنا مجموعي 83 وأعطاني A لكن في ناس مثلا مجموعهم 81 ويعطيهم A+ 🤠 فحاول تخليه يقتنع انك مجتهد حتى لو انك من جنبها.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373610-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/70305/42", "user": "Chelsea_17", "ts": 1401321799000, "tid": 70305, "pn": 42}}]}', 1401321799000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user11005-pe101', 'stk-user11005', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70306", "n": "Dr. Azeem Kaukab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(PE101 - 181 (weight training\nاسمعوا الكلام مني باختصار , اللي يبغى قريد كويس يبعد عنه حتى لو كنت من افضل الطلاب …\n\nالتحضير : متساهل ويحضر بعد 10 دقايق من الكلاس ينادي الاسماء ويسمح بالميك اب…\n\nطريقة الشرح : يقعد يهدر كثير ونصائح غالبا ماتفيد الواحد .\n\nالكويز الورقي : 10 أسئلة على كل سؤال درجتين من 20 ويبغاله مذاكرة\n\nالمياجر: يختبرنا كم اختبارعملي (pre/post fitness test) طبعا يقول كل طالب يحفظ ارقامه ويطلبها كلها دفعة وحدة , طبعا هذي نقطة تغبن لأن الطلاب يكذبون عليه ويعطونه ارقام خطأ بس عشان القريد.\n\nالفاينلات : أعطانا فاينل المطلوب من الطالب انه يرفع 75% من وزنه على 10 أجهزة كل جهاز 15 مرة وطبعا كان يسوي انه مو مهتم فيها لما جاء يقيم وما كان يشوفنا واحنا نسويها بس يمشي على السريع , والمصيبة انه في الاخير نقص تقريبا اغلب الطلاب من 3 الى 5 نسب يقول كنتوا ترفعون الاثقال بشكل غلط (مع انه ماكان حتى يطالع) !!!\n\nالقريد النهائي:D وكثيرعليه بعد\n\nالصوت: واضح\n\nإضافات : الرجال اول عيوبه انه ما يقيم الطلاب بنفسه وينضحك عليه بسرعه يعني لو قلت له انك سويت push up 500 مرة صدّقك وما سأل حتى عن مصداقيتك .\n\nبرضه الرجال يحط قريدات من راسه , اعطاني في آخر الترم A وكنت أستحق A+ وبجداره , في اختباراته حقت الفتنس كنت الاول وكنت أحطم أرقام قياسية وكنت الافضل في كل اختباراته بفارق والورقي جبت فيه فل والغيابات صفر واختبار الفاينل رفعت اكثر من 85% من وزني في كل الاجهزة اللي طلبها والمفروض نرفع بس 75% , رحت عند التشيرمان عشان اقول له بالموضوع حصلت عنده 3 طلاب حتى هم خافس بهم قال خلاص بنادي لكم كوكب تتناقشون معاه ,طبعا أخذنا كوكب لغرفته قال مابزيد احد اي درجة لو ايش وشوي ويدخل في عين الواحد , قلت له طيب علمني ايش نقصت قال لو علمتك بعطيك B+ ولما اصريت عليه قال عندك خطأ في الورقي يعني درجتين ومنقصني برضه 3 درجات في طريقة رفع الاثقال قلت طيب الحين جايب 95 قال الA+ من 96 وقعد يصرف قلت طيب ابغى اشوف اختباري الورقي قال نسيته في البيت.\n\nما اقول غير حسبنا الله ونعم الوكيل وصراحة ما يستاهل يكون في هيئة اعضاء التدريس , ماهمني لو جبت C وانا استحقها بس ليش الظلم وتوزيع القريدات اللي من الراس ؟", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504371-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/azeem-kaukab/70306/26", "user": "user11005", "ts": 1546369358000, "tid": 70306, "pn": 26}}]}', 1546369358000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-brhuggi-pe101', 'stk-brhuggi', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70306", "n": "Dr. Azeem Kaukab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(PE 101- 201 (Weight Training\nONLINE\n\nالتحضير : بداية الترم يعطيك رقم وبعد 10 دقايق او ربع ساعة من بداية الكلاس يبدأ ينادي الارقام بالترتيب وكل واحد لازم يكتب رقمه في الشات\n\nطريقة الشرح : من السلايدات ومحد فاهم له الصراحة مادام الوضع اونلاين\n\nالكويزات : لايوجد\n\nالمياجر: اختبار 20 درجة على الكتاب كامل وعند سلايات\n\nالفاينلات : 20 درجة T/F من نوتات والاسئلة واضحة\n\nالقريد النهائي: B+\n\nالصوت: واضح وممتاز\n\nإضافات : تقييم اغلب الكورس كان بأنك تسوي له اسايمنت سلايدات باور بوينت بشروط معينة ومبالغ فيها وتاخذ وقت كثير ماله داعي، لكن لو سويت كل شيء بالضبط اضمن ال A+ عندك.\n\nالدكتور حبيب وخخلوق الصراحة بس مرات تحس انها قافلة عنده ومرات تحسه فلاوي، اذا ودك تنزل عنده اونلاين تحمل الاسايمنتس اللي بتجيك ممكن 2 او 3 ولازم يكون شغل مرتب عشان ماتضيع درجات مالها داعي.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527433-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/azeem-kaukab/70306/28", "user": "BRHUGGI", "ts": 1609421942000, "tid": 70306, "pn": 28}}]}', 1609421942000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12191-pe101', 'stk-user12191', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70306", "n": "Dr. Azeem Kaukab", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 ( Weight Training) - TERM 212\n\nالتحضير :\nينادي بالأرقام في بداية الكلاس ، ولو تجيه متأخر يحضرك ما يدقق مرة ويقبل الميك اب (تحضر عند سكشن ثاني) وحذف غياب واحد آخر الترم.\n\nطريقة الشرح :\nفي بداية جزئية العملي يسأل الطلاب مين له معرفة سابقة بالآلات ويخليهم يشرحون لطلاب الي مايعرفون شي. بعدين خلاص يجي كل يوم ويقول اشتغلوا ويجلس. واذا شاف احد يسوي تمرين غلط ممكن اذا كان مروق ذاك اليوم ينبهه ويعلمه ان تمرينك غلط. أما النظري يخلي الطلاب يسوون برزنتيشن ويشرحون جزئية النظري ، و يعلق في الأخير على الموضوع إذا خلص الطالب الشرح.\n\nالكويزات :\nكويز واحد سهل نوعًا ما عليه ٢٠ درجة (صح وخطأ ) على جزئية النظري.\n\nالفاينلات :\nالفاينل يطلب منك تشيل متوسط ٨٠% من وزنك على ١٠ آلات ، يخلي طالب عند كل آله يسجل الأوزان الي يشيلونها الطلاب.\nالقريد النهائي:\nB+\nالصوت:\nواضح ، والاكسنت حقه هندي مفهوم.\nإضافات :\nالدكتور بشكل عام أخلاقه جيده ، ويصدق اي شيء يقوله الطالب في العملي لو تقوله شلت ١٢٠ كيلو صدقك وسجل عنده انك شلتها. ولكن مشكلته مستحيل يقبل تناقشه على درجاتك آخر الترم خصوصًا بالغياب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534451-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/azeem-kaukab/70306/29", "user": "user12191", "ts": 1653503982000, "tid": 70306, "pn": 29}}]}', 1653503982000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3767-pe101', 'stk-user3767', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70879", "n": "Dr. Adewale Adejumo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مدرس أكثر من رائع، الله يذكره بالخير…\nأتعب وانا اقول محترم… طيب جداً وقلبه ابيض…\nيهتم كثير للغياب… واللي ما يغيب ممكن يرفعه قريد قريدين…\nاخذت معه pe 101 و pe 102 والحمد لله كلها طلعت بدرجة كويسة…\nأنصح فيه وبقوة…", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p783133-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adewale-adejumo/70879/30", "user": "user3767", "ts": 1297065164000, "tid": 70879, "pn": 30}}]}', 1297065164000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user5712-pe101', 'stk-user5712', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70879", "n": "Dr. Adewale Adejumo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "أخذت معه الكورسين pe101 , pe102\nصراحة الرجال طيب وما يحاسب على التأخير\nوأسئلة الإختبارات مش حالك ويسوي روحه يغشش الطلاب\nيعني بالعربي بتتشقق من الفرح أثناء الدراسة معه\n\nلكن إذا جاء وقت الدرجات تراه ما يعرف أحد ولا يعطيك قريدات حلوة\nلأن القريدات يحطها بناء على الشكل الظاهري للطالب فقط ، لا على أداء الطالب\nيعني تحصله يشوف واحد ضعيف ويقول أن هذا لعيب ، ويقول له من أول إسبوع أنت A+\nولو يجي له واحد متين شوي لو يسوي اللي يسوي ما يعطيه وجه وإذا حصل B+ يحمد ربه\n\nأنا عن نفسي ضبطني وعطاني A ، بس ما عطاني إياه إلا لأني خويه ودايم أمزح معه\nوباقي الطلاب مساكين أكلهم هوا ولا عطاهم قريدات زي الناس\n\nباختصار نزل عنده إذا تبقى ترتاح في السمستر ، وإذا تبقى قريد حسسه انك مجتهد وخله يعرف اسمك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p886976-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adewale-adejumo/70879/35", "user": "user5712", "ts": 1313539896000, "tid": 70879, "pn": 35}}]}', 1313539896000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10547-pe101', 'stk-user10547', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70879", "n": "Dr. Adewale Adejumo", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "151 - pe101\n\nاتحضير : يحضر بالسيريال نمبر ويحضرك لو جيت متاخر\nطريقة الشرح : الهيلث اند فيتنس كانت تجيب النوم لكن نهاية المحاضرات عطانا تحديد للكتاب الصغير وجت منه اسئلة الاختبار\nالقريد النهائي: أخذت a\nإضافات : الدكتور اخلااق وطيب, لكن الدرجات ماش, انا ما عرفت للدكتور الا نهاية السمستر, الدكتور يبيك تشارك معه بالمنافسات بالدوري مثلا ويبي تشوفك تلعب مو مالك خلق تتمشى بالملعب\nوغالبا الي ينزل الدرجات الغياب\n\nاذا تبي تاخذ a+ كل الي عليك تشارك بالدوري حق الكورس ولا تغيب كثير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438660-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/adewale-adejumo/70879/53", "user": "user10547", "ts": 1452571041000, "tid": 70879, "pn": 53}}]}', 1452571041000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmad.ah-pe101', 'stk-ahmad.ah', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70880", "n": "Dr. Ibrahim Sayed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "171 - PE101\n\nالتحضير :\nالتحضير كل كلاس و متعاون مع سالفة انك تحضر بشعبة ثانية اذا كان عندك سبب مقنع\nإضافات :\n-الصراحة انك تنزل عند المادة عنده راح تستفيد بشكل كبير من ناحية شرح وتعامل .\n-راح يسوي لكم اختبار نهاية اللعبة(عملي) و اختبارين (ورقي) + واجب (بونص).\n- متعاون جدا ايام المياجر ، كان عندنا فيزكس وماث ويسال بداية الكلاس اللي عنده ميجر يرفع يده بعدها يحضرك ويقولك امش .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1491161-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-sayed/70880/64", "user": "Ahmad.AH", "ts": 1524118356000, "tid": 70880, "pn": 64}}]}', 1524118356000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-guest-pe101', 'stk-guest', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70880", "n": "Dr. Ibrahim Sayed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 - Health/Fitness/Badminton\n\nالتحضير : يومياً ، و ما يدقق على التأخير لكن لا تطول.\n\nالجزء العملي ( اللعبة ) : اول الأسابيع يعلمك اساسيات اللعبة كل مهارة في كلاسين بعدها يخليكم كل يوم تلعبون ضد بعض .\n\nالجزء النظري ( الكتيب ) : يشرح الكتيب من السلايدات عنده ويشرحه كامل و بالتفصيل .\n\nالاختبارات :\n\nبالنسبة للاختبار العملي تختبرون على كل مهارة في اللعبة ويقيمك عليها . بالنسبة للاختبار النظري في اثنين : واحد على قوانين اللعبة \\( صح وخطأ و اختيارات \\) . والثاني من الكتيب \\( صح وخطأ و اختيارات \\) .\nالصوت : واضح لكن الأكسنت يبي لك تتعود عليه .\n\nإضافات :\n- الدكتور طيب من ناحية التعامل مع الطلاب وما يقصر معاهم .\n- ايام المياجر يسأل الطلاب اللي عنده ميجر يحضر ويمشي .\n- يسمح بالحضور في شعبة ثانية ولكن اذا كان عندك سبب مقنع .\n- عنده واجب عليه بونص .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1501845-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-sayed/70880/66", "user": "Guest", "ts": 1541325556000, "tid": 70880, "pn": 66}}, {"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(عن بعد ) PE 101 - Term 201 - Basketball\n\nالتحضير : ينادي بالاسماء آخر 5 دقايق من المحاضرة و يقبل الميكب اب .\n\nالشرح : يشرح من سلايدات و من الاونلاين كورس و مرات يشغل مقاطع من اليوتيوب عشان يشرح و يوضح بعض المهارات .\n\nالواجبات : اعطانا 3 واجبات ، حذف واحد و دبل درجة واحد ( طبعا كلها سهلات و نسخ و لصق )\n\nالاختبارات : اختبارين ، واحد عن ال Health و واحد عن ال Basketball\n\nبشكل عام انصح و بقوة بالدكتور في الاونلاين لانه ما يشغلك بالتمارين ، ايضا لو باقي لك درجة او درجتين على القريد بيعطيك اياهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527434-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/68", "user": "Guest", "ts": 1609422546000, "tid": 80975, "pn": 68}}, {"id": "stk-dr-f175801", "n": "Dr. Martin Pacholek", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE101 - T201 (عن بعد)\nالتحضير : كل واحد يقول رقمه اللي الدكتور أعطاه إياه في بداية الترم\nطريقة الشرح : الجزئية اللي كان فيها شرح كان إما أن يشرحها هو مثل في قواعد رياضة كرة الريشة (هذي الرياضة اللي أنا منزلها عنده) أو إما أنه يقسم الدرس لأجزاء ويقسم الطلاب إلى مجموعات وكل مجموعة تشرح الجزئية المعطاة لها (هذا اللي كان يسويه في أول 5 أسابيع من الترم في جزئية التعليم الصحي اللي ندرس فيها السكر وضغط الدم إلخ…)\nالكويزات : يوجد اختبار health test بعد أول 5 أسابيع وعليه 20 درجة (تقريبا هو أكبر اختبار) ثم يوجد اختبار ثاني على قواعد اللعبة اللي تدرسونها وعليه 10 درجات\nالمياجر: -\nالفاينلات : -\nالقريد النهائي: أعطيه A\nالصوت: ممتاز (عن بعد)\nإضافات : الدكتور أعطانا 3 مهام في الترم، كلها مهام تصور فيها فيديو ولكن الأولى تصور فيديو وأنت تؤدي تمرين رياضي (أي شيء) ثم الثانية تصور فيديو وأنت تؤدي تمرين في الرياضة اللي أنت قاعد تدرسها والمهمة الثالثة تشبه الأولى ولكن لما تسوي تمرين لازم تشرح معلومات عنه وعن العضلات اللي داخلة في التمرين. الدكتور خلوق.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527440-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/martin-pacholek/175801/13", "user": "Guest", "ts": 1609445633000, "tid": 175801, "pn": 13}}]}', 1541325556000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-sultan_salman_1419-pe101', 'stk-sultan_salman_1419', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70880", "n": "Dr. Ibrahim Sayed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 ( Badminton ) …Term 181\n\nالتحضير : مرات في البداية ومرات في النهاية … لو حضرت متأخر وكلمته ما أتوقع بيقصر معك …\n\nطريقة الشرح : الشرح شمل الجزء النظري باستخدام السلايدات … جيد جدا بشكل عام\n\nالكويزات : كويزين … بيعطيك مجموعة من الاسئلة المتوقعة في الكويز قبلها بأسبوع … لو ذاكرتها بتجيب درجة كاملة بسهولة\n\nالمياجر: الجزء العملي من الكلاس … بسيط طالما تعرف تلعب ريشة ( بيعطيكم وقت كافي للتمارين )\n\nالقريد النهائي: A+\n\nالصوت: مسموع بشكل عام\n\nإضافات :\n\n1- دكتور محترم كأخلاق ومتعاون ويعاملك كابن له\n\n2- ما عنده مشكلة في الميك اب بس لا تزودها وكلمه قبل أفضل … عن نفسي سويتها مرتين بعلم مسبق ومشت معي\n\n3- قريدك النهائي بيكون قريدك اللي تعبت عليه + قريد كامل ( +5 درجات )\n\n4 - الA+ مقدور عليها بسهولة بس لا تغيب واعط اللعبة حقها", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504156-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-sayed/70880/67", "user": "sultan_salman_1419", "ts": 1545924454000, "tid": 70880, "pn": 67}}]}', 1545924454000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-paco-pe101', 'stk-paco', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70880", "n": "Dr. Ibrahim Sayed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(Pe101 Badminton - 201 (Online\n\nالتحضير : نهاية المحاضرة بالاسماء\n\nطريقة الشرح : الجزء النظري من سلايدات والعملي ورانا فيديوهات لطريقة التمارين وصرنا نسويها كل محاضرة\n\nالكويزات : لا يوجد\nالمياجر: لا يوجد\nالفاينلات : لا يوجد\n\nالقريد النهائي: A+++\n\nالصوت: واضح\n\nإضافات :\nالدكتور اخلااااق وما يقصر بالدرجات\nبالنسبة للجزء النظري طلب نسوي بحث والعملي عطانا شارت نعبي فيه التمارين الي سويناها بس", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527728-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-sayed/70880/72", "user": "Paco", "ts": 1610189680000, "tid": 70880, "pn": 72}}]}', 1610189680000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_as1-pe101', 'stk-_as1', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70880", "n": "Dr. Ibrahim Sayed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Dr. IBRAHIM SAYED / د. إبراهيم سيد\n\nالمادة ورقم الترم: PE101 & T201 (Online)\n\nبنود التقييم /\n\nالتحضير : ياخذ التحضير في نهاية الكلاس عن طريق ينادي بالأسامي وانت تكتب له بالـ \" BB collaborate \" كلمة \" Yes \" أو اي شيء عشان يشوف اسمك أو أفتح المايك … أنت وقتها أفتح البلاك ثم كلم احد يرجعك اذا حضّر أو الواتس مايقصرون\n\nطريقة الشرح : يشرح مع سلايداته عن المنهج كل سلايده يتكلم فيها ويقعد ينصح ويحاول يفيدك بالمنهج ويستعمل فديو ،غالبا كلاساته ماتطول بين 30 - 45 دقيقه مرات عادي تطلع بعد 20 دقيقه ومايهتم أنك متابع معه ولا لا … بعد 7 أسابيع لأنه كنا أونلاين ماكنا نقدر نلعب اي رياضية … يقعد يصور نفسه وهو يسوي تمارين أحماء ثم تمارين شوي أدفانس ويطلب تسوي معاه وبعدها يجيك الجزئية اللي كل طلابه حافظينها وهي عبارات إسترخاء ههههههههههههههههههههههه\nيقول : \" … … … Close your eyes slowly and slowly and REELLLAAAAXXX \" وبعدها ينادي بالأسماء للتحضير\n\nالكويزات : حرفيا … None عكس كل الدكاترة احترم ضغوطاتنا ولا طلب منا ولا كوز ولا نهائي ولا اي شي يقيم فهمنا ، جدااا طيب ومحترم ومتفهم وأصلا هو ماخذ كلاسه للفايده مايبيك تأخرك على كلاساتك وتشغلك عن ما هو أهم وأعلى كريدت وحتى في عبارة دايما يكررها \" Don’t Worry , relax \"\n\nالمياجر: None\nالفاينلات : None\n\nالقريد النهائي: A+++++++++++++++… أخاف أكمل الـ + ويخلص شحن الجهاز\n\nالصوت: صوت قوي وواضح وأكسنت هندي مخفف\n\nإضافات : مع ذا الدكتور نزل الكورس وأنساه ورجع نهاية الترم فيه A+ جتك وانت ماتدري ، لكن انتبه عالغياب\n\nفي تكليفين عطانيا اياه طول الترم فقط وهو مجبور عليها ولا مايبي يضرك اللي هم :\n1.تكتب نص صفحة Word عن أحد المواضيع الصحية المذكورة فالواجب (يمديك تزرفه من النت في 30 ثانية تسويه)\n2. جدول رياضي تكتب عدد مرات التدريب مع الوقت ( يمديك تكيّس أرقام من عندك وتخليها واقعية أو خويك مايقصر ماياخذ دقيقتين )\n\nتخيل كورس كامل مع أربع شهور تخلص بـ نص ساعة كـ تحضّر نفسك مع التكليفين … تمنيت انزل PE102 عنده لكن جدولي حذفوه بالخطه الجديدة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1529913-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-sayed/70880/73", "user": "_As1", "ts": 1620495029000, "tid": 70880, "pn": 73}}]}', 1620495029000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ria-pe101', 'stk-ria', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f70880", "n": "Dr. Ibrahim Sayed", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 TERM 201 (ONLINE)\n\nالتحضير : ينادي بالاسامي\nطريقة الشرح : يشرح من السلايدات\nالكويزات : مافي كويزات (كان بس بحث 10 سطور عليه 40 درجة و work sheet تكتب عليها كم سويت تمارين عليها 60)\nالمياجر: مافي\nالفاينلات : مافي\nالقريد النهائي: A+++++++++++++\nالصوت: عالي وواضح\nإضافات : الدكتور مره طيب واخلاق ومتفهم لابعد درجة لو تقله انا عندي ميد او ميجر يقلك ارسلي اميل برقمك الجامعي وبحضرك", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1531686-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ibrahim-sayed/70880/74", "user": "RIA", "ts": 1630847797000, "tid": 70880, "pn": 74}}]}', 1630847797000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mha14-pe101', 'stk-mha14', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f73559", "n": "Dr. Hassan Almoslim", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101-131\nBadminton (ريشة)\nالتحضير:\nبداية الحصة واحيانا في النهاية, يسمح بالتأخير\nماعنده مشكلة بالميك اب\nالشرح:\nجيد ويتقبل الاسئلة\nالكويزات:\nما فيه\nاختبار اللياقة:\nاسوء شي في الدكتور هو ختبار اللياقة(الفيتنس تيست),هلك بشكل مو طبيعي\nيفكر الطلاب يلعبو العاب اولومبية\nالصوت:\nواضح, واللهجة حلوة\nالقريد:\nA+++", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1317151-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hassan-almoslim/73559/32", "user": "MHA14", "ts": 1389170127000, "tid": 73559, "pn": 32}}]}', 1389170127000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-asmarica-pe101', 'stk-asmarica', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f74753", "n": "Dr. Hong Jun Choi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE101 - 141\n\nالتحضير يوميا في بداية الحصة ويسامح في التأخير\n\nاختبار ال health سهل و يحدد قبله الاسئلة\n\nويعطي بونص في الاختبار و احيانا على اشياء ثانية\n\nببساطة لا تغيب و جيب فل مارك في الاختبار و لا تضيع البونص وما راح تنزل عن الA", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1420517-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hong-jun-choi/74753/39", "user": "Asmarica", "ts": 1421664478000, "tid": 74753, "pn": 39}}]}', 1421664478000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zeroal-pe101', 'stk-zeroal', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f74753", "n": "Dr. Hong Jun Choi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE101(Basketball)-Term211\n\nالتحضير : شديد جدآ لو ما كان يتأخر شوي كان بلعت غيابات لليل. يذكر ان الغياب درجتين والتأخر بدرجة. اللي يجي بعد ما يمشي رقمه تأخير لكن بالاغلب بيخيرك تأخير ولا عشرة ضغط\nطريقة الشرح : اول اربع اسابيع يشرح عن الصحة بعض الاحيان يخلص قبل نهاية الوقت. بعدها بالبداية يتكلم شوي ويخلينا نلعب.\nالكويزات : عطانا كويز عن الHealth education سهل مرة يعطيك الاسئلة قبلها وفيه بونص درجة. والفزكال فتنس عطانا درجته ماسواه\nالمياجر: المد كان شوي مصعبه 25 على المهارات و 5 على الفري شوت تضيع وحدة تروح عليك درجة\nالفاينلات : ذيبان قال منب مسوي لكم فاينال اللي عليكم تحضرون باقي المحاضرات\nالصوت: واضح\nالقريد النهائي: A\nإضافات : أهم شي عنده الحضووور. وضبطنا مرة بالبونصات سوا ثلاث مباريات الفريق الفايز بونص, وسوو بطولة للسكاشن لو حضرت بس تسجل اسمك عنده ويعطيك ثلاث درجات بونص.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533306-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/hong-jun-choi/74753/50", "user": "zeroal", "ts": 1641331862000, "tid": 74753, "pn": 50}}]}', 1641331862000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-asem007-pe101', 'stk-asem007', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "pe101\nاستاذ ممتاز\nالتحضير صارم فيه ومع اللايتات كمان\nيشرحلك التمرين اونت تسويه\nمافيه مياجر ولا كويزات كل ما خلصت لعبة يختبرك عليها\nهو طبعا يدرس باسكتبال واذا انت ممتاز يكون احسن\nكل ما عليك انك تورية انك مهتم في المادة وتستعرض قدامة خخخخخخخ 😃", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p788573-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/30", "user": "asem007", "ts": 1297602709000, "tid": 80975, "pn": 30}}]}', 1297602709000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-_716-pe101', 'stk-_716', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "pe 101 term121\n\nالتحضير : يومياً وانتبه تغيب لأن فيه خصم\nطريقة الشرح : الشرح هو أغلب الحصة تقريبا 5 إلى 10 دقايق نلعب سلة\nالكويزات : سهلة نسبياً حاول تضبط فيها\nالمياجر:مافيه\nالفاينلات : مافيه\nالقريد النهائي:b+\nالصوت: واضح ويتكلم أحياناً عربي\nإضافات :\n\nأنا بصراحة مانيب حق رياضة في الأوريا جبت c و d+\n\nالسمستر هذا ماغبت وكان فيه بونص ولا سلمته وعطاني b+\n\nبمعنى لو بتجيب a يبيلك تجيب البونص اللي يقوله في الهيلب فتنس + تحضر دوري السلة", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1164479-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/40", "user": "_716", "ts": 1358233442000, "tid": 80975, "pn": 40}}]}', 1358233442000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-practice-pe101', 'stk-practice', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE101 - Term 122 Basketball\n\nالتحضير :\nيحضر كل كلاس وكل تاخير خصم درجة وكل غياب خصم درجتين ومتشدد جدا\nيسمح بالميك اب طوال الترم\nيقول انت بس لا تغيب ولا تشيل هم\nانا كان عندي غياب واحد ولعبي عادي اعطاني b+ مع اني سلمت البونس حق الهومورك وحضرت الدوري\n\nطريقة الشرح :\n\nمهتم جدا وماخذ المادة بجدية , يشرح طول الوقت بالانقليزي وما يحب احد يتكلم بالعربي لما يشارك\n\nمافي لعب كثير , يعني مافي مباريات طويلة كلو من ابو 10 دقايق والباقي تطبيق وتعليم\n\nالكويزات :\nكويزين وسهلة مرة وواضحة وفيه بونس هومورك وبونس مشاركة في الدوري\n\nالفاينلات : فاينل السلة كان خفيف وتافه وما طلب شي عليه الكلام\nالقريد النهائي: B\nا\nلصوت: عالي مرررررة ومبحوح من النوع اللي يرفع الضغط p:\n\nإضافات :\nتمنيت اني ما نزلت معاه لانه شديد جدا وعصبي يعني يعصب احيانا على شي جدا تافه\nيحب يمزح ويتريق على الطلاب *محشات سامجة*\nاخذ المادة بجدية وممكن كثيرين ما يعجبهم الشي ذا وانا اولهم\n\nفي النهاية ما انصح فيه الا لو انحديت لانو فيه نوع من القلق , بس لو نزلت معاه تقدر تسلك له وتمشي وضعك وفي النهاية a\n\nموفقين", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1251701-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/41", "user": "Practice", "ts": 1375748354000, "tid": 80975, "pn": 41}}]}', 1375748354000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abu_hamad_22-pe101', 'stk-abu_hamad_22', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 -- Term 131\n\nالتحضير : بداية الكلاس و شديد بالتحضير و التأخير\nطريقة الشرح : يشرح الجزء اللي بيشرحه من اللعبة … مثلاً بالسلة يشرح كيف تمرر و كذا … و شرحه روعة مع تطبيق\nالكويزات : كويز حق الفتنس سهل و حق السلة جداً سهلين\nالمياجر: مافي\nالفاينلات : فاينل عملي حق السلة بالخمس مهارات … تمرير و كيف تمر بين الاقماع و التسديد بأنواعه الثلاثة\nالقريد النهائي: A\nالصوت: جداً واضح و لغته ممتازة ما شاء الله عليه\nإضافات : الدكتور حبيب و أخلاقه مرة عالية … لدرجة جيته هذاك اليوم كنت مُصاب قال لي آستريح و يقدر الظروف و يسمح بالميك آب\n\nو إذا حضرت دورة السلة اللي بالليل و جيت لابس لبس رياضي بونس 5 و إذا بدع السكشن ممكن يوصل بونس 8", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1311599-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/43", "user": "Abu_Hamad_22", "ts": 1388360251000, "tid": 80975, "pn": 43}}]}', 1388360251000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-imxpz-pe101', 'stk-imxpz', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 - Term 131\n\nالتحضير : شـديد بآلغيآبآت وآلتآخير. يحذف غيآب وآحد للطآلب.\n\nطريقة الشرح : جدآ مثقف وحمآسي , بديت م آعرف شيء بآلسلة وآنتهيت آستمتع بمبآريآت كرة آلسلة وآلتكتيك آللي يتبعونه.\n\nالكويزات : كويزآت آلفتنس وآلسلة سهلة. مآ يحب يعقد على الطآلب.\n\nالمياجر: لآ يوجـد .\n\nالفاينلات : فاينل عملي حق السلة خمس مهآرآت …\n1- آلتمرير - Passing\n2- آلمرور بين آلآقمآع … dribbling\n3- رمى آلكرة مع آلقفز … Jump shoot\n4- رمى الكرة مع آلثبآت standing shoot\n5- رمي آلكرة مع آلجري …\nيسمح بإعآدة آلمهآرة مرة ومرتين للحصول على درجة آفضل. ❤️\n\nالقريد النهائي: A++++++\n\nالصوت: وآضـح …\n\nإضافات : الدكتور حبيب آسم عـلى مسمى , حمآسي , مثقف , يعرف آلمآدة آللي يدرسهآ.\nكريم جدآ بآلدرجآت … يعطيك آكثر ممآ تستحق … يعطي بونسآت.\nخمس درجآت علـى آلحضور للـ تورنمينت , وبونص لآفضل Passing فـآلكلآس\n\nبآختصآر شديد : آلدكتـور رقم وآحد بـ قسم آلـ PE من وجهة نظري … آنصـح آلـطلاب فيه.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1320048-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/49", "user": "iMxPz", "ts": 1389881472000, "tid": 80975, "pn": 49}}]}', 1389881472000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.a1-pe101', 'stk-mr.a1', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "تقييم\nالأستاذ حبيب الربعان\nمحاضر\n\nعلى فكرة تراه دكتور ، بدرجة أستاذ مشارك\n\nTERM 151 PE 101\n\nبنود التقييم :\n\nالتحضير :\nبداية كل محاضرة ، ينادي بالأسماء. يسمح بحضورك خارج سكشنك ، احيانا يتكلم في موضوع الحضور خارج السكشن بس ما يمانع\n\nطريقة الشرح :\nأول شهر كان عبارة عن Health & Fitness ، شرح بسيط وتوضيح لبعض الأخطاء في الكتاب.\nبعد كذا راح تدخل معه على كرة السلة ، شرح مفصل ودقيق جدا لمهارات اللعبة بالإضافة لبعض القوانين ، مع تطبيق عملي موضح جدا\n\nالكويزات :\nكويز الكتاب بعد نهاية أول شهر سهل جدا ، كل اللي يحتاج منك إنك تحفظ كويس وتجيب درجة بسهولة ، عبارة عن صح وخطأ واختر الاجابة\n\nالمياجر:\nلا يوجد\n\nالفاينلات :\nينقسم الفاينل إلى ٣ أقسام:\n١. تقييم على اللعب في مباراة.\n٢. اختبار على المهارات الخمس اللي راح تتعلمها خلال المحاضرات\n٣. اختبار قوانين اللعبة ، عبارة عن ١٠ أسئلة صح أو خطأ عن قواعد اللعبة\n\nالقريد النهائي:\nعطاني A ، اعطيه +A\n\nالصوت:\nمبحوح وعالي جدا\n\nإضافات :\nيا لبى قلبه ، من أروع الدكاترة اللي اخذت معهم المادة\nعنده بونص كثير جدا ، أول بونص كان عبارة عن بحث حول ٣ نقاط في الكتاب وتقييمها من ٣ إلى ٥ درجات ، وثاني بونص كان منافسة بين الطلاب حول مهارة التمرير وأفضل طالبين ياخذون البونص ، وآخر بونص كان حول مسابقة السلة ، كل اللي حضروا المسابقة وهم لابسين زي رياضي أخذوا بونص ٥ درجات عليها.\nفي اختبار المهارات يعطيك فرص كثيرة حتى تحقق أفضل درجة فيها\n\nرأيي الشخصي: إذا حصل لك الربعان سجل معه واشتغل في اللعبة واستمتع فيها ، وراح تشوف اللي يرضيك\n\nأرسلت بواسطة iPhone بإستخدام Tapatalk", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1436838-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/51", "user": "Mr.A1", "ts": 1451048548000, "tid": 80975, "pn": 51}}]}', 1451048548000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rygart-pe101', 'stk-rygart', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE101-151\nالتحضير : كل محاضرة يحضر ، يحضر بعد خمس دقايق من المحاضرة ، اللي يتأخر أكثر من عشر دقايق يقوله تعال مع سكشن ثاني .\nيسمح تحضر مع سكشن ثاني بس كم مرة يتكلم عن الموضوع هذا بس ما راح يطردك .\n\n* كان معنا طالب من سكشن ثاني حضر كل محاضرته مع سكشنا ، فـ لو تكلمه بداية الترم إنك بتحضر على طول مع سكشن ثاني\nأتوقع يوافق\n\nطريقة الشرح : شرح بسيط المادة اصلا ما يبي لها شرح\n\nالكويزات : الكويز الأول كان سهل و جاب من الاشياء اللي حددها ، طبعا الكتاب فيه اخطاء لذلك لازم تعدلها معاه لأنه يجيب منها .\nالكويز الثاني حق قوانين السلة كان كله صح و خطا وكان سهل جدا !\n\nالفاينل مثل ما قال اللي فوق\nالفاينلات :\nينقسم الفاينل إلى ظ£ أقسام:\nظ،. تقييم على اللعب في مباراة.\nظ¢. اختبار على المهارات الخمس اللي راح تتعلمها خلال المحاضرات\nظ£. اختبار قوانين اللعبة ، عبارة عن ظ،ظ* أسئلة صح أو خطأ عن قواعد اللعبة\n* تعيد اي مهاراة اخذت فيها درجة اقل من 6 وهو راح يقولك عليهم .\n\nالقريد النهائي: اعطيه A+\n\nالصوت: واضح ومسموع و لغته الانجيلزية كويسة\nإضافات :\nالدكتور أخلاق و فاهم في السلة ، طبق اللي يقوله و بتلقى نتائج طيبة\nبديت اعرف قوانين السلة فقط ، و خلصت وانا اعرف العب xD\n*من مميزات الدكتور كان فيه أكثر من بونص:\n*حط لنا هومورك فيه مواضيع و قال جيبوا بحث عنها مع المصدر ، عليه من 3-5 درجات < نسخ و لصق من النت و ثلاث درجات بالجيب\n* بونص لـ افضل 2 في التمرير\n*بونص حضور المسابقة حقت السلة وعليها 5 درجات للحضور فقط ولو سكشنكم اخذ البطولة تصير 7 درجات\n5 درجات ممكن ترفعك من A الى A+\n\nعن نفسي ما غبت ولا غياب ، سويت الهومورك ، ما حضرت المسابقة حقت السلة و طلعت بـ A", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1437704-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/53", "user": "Rygart", "ts": 1451700985000, "tid": 80975, "pn": 53}}]}', 1451700985000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-fay16-pe101', 'stk-fay16', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 term 151\n\nالتحضير :\n\nبداية المحاضرة ولا تتأخر ولا تغيب .\n\nطريقة الشرح :\n\nيجمع الطلّاب ويبدأ يشرح ربع ساعة بعد كذا يخليكم تطبقّوا اللي شرحه وآخر 10 دقائق يخليكم تلعبون\n\nالكويزات :\n\nعطانا كويزين يبغالك تذاكر لها بجد كل كويز من 10\n\nالقريد النهائي:\n\nc+\n\nالصوت:\nواضح وعالي\n\nإضافات :\n\nكان عندي غياب أو غيابين + عنده 2 بونص ( بحث عليه 3 درجات + حضور البطولة 5 درجات ) نفذتها له كلها .\nوكنت متفاعل معاه وبالفيتنيس وضعي طيب لأني ألعب كرة قدم كثير وجسمي رياضي إلى حد ما ( الكورس كان سلّة )\nالمهم خسفتني الكويزات جبت فيهم 7 من 10 .\nوتقييمه شديد في السكيلز حقت اللعبة .\n\nكنت أطمح إني أطلع ب A+ أو A لكن عطاني B ولما سألته قاللي درجاتي وطلعت c+ وهو عطاني B\nالدكتور أحياناً يعصّب ويرفع صوته على أشياء تافهة يعني يشرح شغلة هامشية بشكل مبسط وإذا شاف واحد أخطأ فيها ممكن يصارخ ويقول أنا ما أعرف أنتم كيف تفهمون ولا أنا ما أعرف أشرح ولا أدمغتكم فيها شيء ومن الكلام هذا .\n\nفي فكرة منتشرة عند الطلّاب إنه الكورس عنده زي الفيزيكس من كثر ما يعقّد الأمور .\n\nمن وجهة نظري اللعبة اللي بتنزلها عنده حاول تكون اللعبة هذي هوايتك وأنت لعيب فيها لأنه بيقيم على السكيلز بدقة وبيتعبك فيه\n\nالدكتور غاب تقريباً 4 محاضرات وكان واحد من الطلّاب يمسك المحاضرات عنه وفي تحضير", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438681-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/54", "user": "fay16", "ts": 1452593843000, "tid": 80975, "pn": 54}}]}', 1452593843000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tryagain-pe101', 'stk-tryagain', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور : حبيب الربعان\nPE 101 Basketball\nTerm 151\n\nالتحضير : يحضر كل حصة بعد مرور 5 دقائق من الحصة … الغياب والتأخير عندو مؤثر جدا فلا تغيب ولا تتأخر … ويسمح بالميك اب … بشرط يكون في متسع في السكشن\n\nالكويز : في كويزين … كويز نهاية قسم الفيتنيس وهو بحاجة الى مذاكرة ممتازة … يعني المذاكرة السريعة ما تنفع … هذا الكويز يكون صح وخطأ واختيارات … الثاني عن قوانين السلة وايضا بحاجة الى تركيز … 10 فقرات صح وخطأ …\n\nالدكتور لطيف وتعامله معك ممتاز لكن لازم تكون منضبط معاه بشكل كبير …\n\nالسكيلز يحاول يشدد فيها شوي فحاول تتدرب قبل الاختبار …\n\nعندو 8 درجات بونص في الجيب … 3 على البحث وممكن تزيد الى 5 اذا كان بحثك مرتب … و 5 لحضور المسابقة وقد تزيد ل 8 اذا سكشنكم اخذ البطولة …\n\nدرجاتي كانت … 18 من 20 في اول كويز … و فل في الثاني … وكنت جيد في السكيلز … وعندي 3 تأخيرات لكن ولا غياب … وطلعت ب A+ الحمدلله …\n\nالدكتور مشكلته الوحيدة هي انو يعطي المادة اكبر من حجمها … يعني تحس كأنك منزل فيزكس مو PE … اذا ما عندك مشكلة مع هذي النقطة نزل عندو …\n\nالتقييم النهائي : A\n\n🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438691-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/55", "user": "TryAgain", "ts": 1452598896000, "tid": 80975, "pn": 55}}]}', 1452598896000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10207-pe101', 'stk-user10207', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 - Term 151\n\n- يحضر بداية الكلاس.\n- الحضور مهم. الخصم بدرجتين.\n- تقدر تحضر مع سكشن ثاني.\n- أول خمس اسابيع، كان فيه شرح نظري عن اللياقة، ارتفاع وانخفاض ضغط الدم، مرض السكري، الانعاش القلبي الرئوي، …\n- موجودة السلايدات في موقعه.\n- اختبرنا على الكلام الي درسناه. سهل وكلها اختيارات وصح وخطأ.\n- من الاسبوع السادس الى آخر اسبوع كرة سلة.\n- بالبداية يحضر ويشرح قواعد او مهارات لكرة السلة. وآخر 10 دقائق لعب كرة سلة.\n- آخر اسبوع كان فيه فاينل على كرة السلة. فيه نظري وفيه عملي.\n- يعطي فرصة باختبار كرة السلة اذا درجتك تحت الافرج.\n- الاختبار النظري كان عن قوانين كرة السلة. موجودة بموقعه.\n- يعطي بونص. بداية الترم اعطى هومورك بونص.\n- في الاسبوع الـ 12 كان فيه بطولة كرة السلة ويعطي بونص خمس درجات الي يحضر.\n- أنصح الطلاب يسوون البونص هومورك ويحضرون المسابقة لانه هذي فيها قريد + 3 درجات.\n- فيه بونص بعد على افضل تمرير.\n- الصوت جداً عالي.\n- يشرح بالعربي وشوي بالانجليزي. لغته الانجليزية سيئة.\n- نفس كلام الطلاب، الدكتور يعطي المادة اهتمام.\n- الدكتور جداً محترم وطيب.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1438765-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/56", "user": "user10207", "ts": 1452650387000, "tid": 80975, "pn": 56}}]}', 1452650387000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user10703-pe101', 'stk-user10703', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور حبيب الربعان -pe101-ترم152\nالكورس اغلبه كره سله\nطيب الدكتور شديد حبتين في تدريس الماده يسوي مابوسعه لكي تفهم وتطبق صح شخصيا كنت خايف يوم سجلت معه اني بجيب العيد لاكن طلعت بالكورس بA وماتوقعت بطلع بكذا على كلام بعض الاخوة سونا لنا اختبارين تحريري واحد في الكتاب عليه 20 درجه بعد اول شهر تمتحنونه متوسط ماهو سهل ولاصعب عبارة عن 10 فقرات صح وخطأ وخيارات جبت فيها 16 وسوى اختبار على قواعد كرة السله عليها 10درجات جبت 8 كلها صح وخطأ بالنسبه للفتنس كانت اللياقه حقتي عاديه ويمكن اقل من عاديه ومهارات كرة السله عادي جدا سوى لنا 8 درجات بونص يعني مهمه استفد منها وحاول ماتغيب وبتجيب قريد حلو وهو بعد يزيدك قريد في النهاية يعني اذا مجموعك يجيبلكBهو يخليها +Bوهكذا تقييمي لهذا الدكتور +B", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1452623-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/58", "user": "user10703", "ts": 1466651314000, "tid": 80975, "pn": 58}}]}', 1466651314000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah2015-pe101', 'stk-abdullah2015', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "دكتور حبيب الربعان\nأخذت عنده PE 101 (كرة السلة) ترم 161\n\nفي بداية الكورس كان فيتنس وصراحة الاختبار كان صعب ويحتاج مذاكرة عدلة، يجيب أشياء تخربطك، بمعنى مذاكرة ليلة الاختبار ما راح تفيدك، يعني يجيب فيه أرقام بين السطور ومن الجداول وكذا، إذا ما كنت مستعد بشكل جيد بتجيب العيد في الاختبار. طبعًا محدثكم جاب العيد في المذاكرة للاختبار على أساس إنه الاختبار بيكون سهل وما ركزت كثير على بين السطور وجبت درجة نازلة نسبيًا.\n\nوكذلك في نهاية الفيتنس عطانا هوموورك (اختياري) اللي يحله ياخذ ثلاث درجات بونص، الواجب عبارة عن بحث وشوي طويل لأن يعطيك لستة مواضيع تختار منها على الأقل ثلاثة مواضيع، وكل موضوع لازم تتكلم عنه من ثلاث مصادر على الأقل، أنا أخذ مني حوالي 4 ساعات شغل، نصيحة لا تفوته، أقول هالكلام لأن أغلب الشباب اللي معي في السكشن ما حلوا الواجب (بحسب كلام الدكتور).\n\nجا بعدها الجزء العملي، وبصراحة كرة السلة ممتعة (للي يحبها)، الدكتور يحضر بداية الحصة ومن ثم يبدأ يشرح مهارة ونبدأ نطبقها بشكل عملي، وآخر جزء من الكلاس يقسم الطلاب إلى أربع فرق ويبدأون يلعبون كل فريقين ضد بعض، هذا الروتين اليومي لكلاس الPE مع الدكتور.\n\nفي أثناء السمستر بيكون فيه بونصات لأفضل الطلاب اللي يسوون بعض الأشياء ، مثل أفضل تمرير بيأخذون بونص، فيه بونص ثاني مرة من المرات قسم الطلاب إلى فريقين والفريق اللي يسجل أهداف أكثر في السلة بنظام الFoul Shoots بيأخذ بونص … ففيه بونصات كثيرة\n\nوآخر الترم كان فيه مسابقة كرة سلة بين السكاشن، واللي يحضر (كمشاهد فقط) بيأخذ بونص 5 درجات…\n\nيعني من دون البونصات اللي أثناء اللعب، كل طالب بيده 8 درجات بونص (3 الهوموورك الاختياري + 5 مسابقة كرة السلة آخر الترم)\n\nالاختبار النهائي فيه اختبارين، عملي ونظري، العملي باختصار بيختبرك في المهارات اللي تعلمتها في أثناء الكورس، والنظري بيختبرك في قواعد كرة السلة (بيعطيكم ملخص تذاكرون منه).\n\nالاختبار التحريري لقواعد كرة السلة، الاختبار كان صح وخطأ وكان سهل جداً بعكس اختبار الفتنس\n\nيعني لو حاضر المحاضرات ومركز أقل شيء بتطلع من الاختبار 6 أو 7 من 10 (درجة تقريبية لأن أغلب الاختبار كان بديهي جداً لواحد كان يلعب كرة السلة لمدة ترم كامل)\n\nيعني لتقريب الفكرة، هو زي لما يكون كورس كرة قدم وأجيب لك في الاختبار الفقرة الآتية:-\n\n- عدد لاعبين الفريق الواحد المتواجدين في الملعب في كرة القدم 11 لاعب. (صح أم خطأ)\n\nطيب نجي للجزء الأهم بالنسبة للأغلبية ألا وهو القريدات، أشوف إنه كثير من الشباب حصلوا على A وكان أدائهم في الكورس (أفرج) ما كانوا مرة متقنين المهارات\n\nوأنا من ضمنهم حصلت A مع إني جبت العيد في مهارتين في الاختبار النهائي العملي، ودرجتي في الاختبار الفتنس كانت شوي نازلة …\n\nلذلك بصراحة أنصح بالدكتور (إذا كنت من محبي كرة السلة) …\n\nوبالتوفيق 🙂", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1466953-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/59", "user": "Abdullah2015", "ts": 1485298924000, "tid": 80975, "pn": 59}}]}', 1485298924000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-dew-pe101', 'stk-dew', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "pe101 161\n\nبنود التقييم :\n\nالتحضير :يحضر بعد خمس دقايق من بدايه الكلاس… وغالبا ما يسمح احد يحضر بعد التسخين… يسمح بالميك اب\nطريقة الشرح :يشرح فالبدايه ويعطيكم نبذه عن الي بتاخذونه…\nالكويزات :كوبزاته سهلا نسبيا لو تذاكر زين\nالمياجر:-\nالفاينلات :-\nالقريد النهائي:A+\nالصوت:واااااضح وضوح الشمس ما شاء الله عليه\nإضافات :عطانا بدايه السمستر واجب بحث نسويه نرسله له عليه 3 درجات+سوا مسابقه بأحد الكلاسات والفريقه الفايز درجتين بونص+ فيه بطوله يسوونها نهايه السمستر اذا حضرت 5 درجات بونص واذا فاز سكشنكم تصير 8 درجات بونص انت بس انضبط معه وجيب درجات زينه بالكويزات وبتاخذ a+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1468543-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/60", "user": "Dew", "ts": 1487378378000, "tid": 80975, "pn": 60}}]}', 1487378378000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-bader_alqahtani-pe101', 'stk-bader_alqahtani', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Pe101 term172 basketball\nاخذت الكورس مع الدكتور ذا الترم الثاني و بسم الله نبدا تقيمه\n\nالتحضير:يحضر بالتايم و يدقق عليه و يسجل تأخير +يقبل الميك اب بس لازم ترسله قبلها بليلة انك بتسوي ميك اب ولا بيطلعه من عيونك و يقعد يسفل فيك قدام الطلاب\n\nالشرح:المادة م تحتاج شرح صراحة بس هو كشرح يسوي الي عليه\n\nالاختبارات: فيه اختبارين ورقية غير العملي الي هو بعد م تخلصون الكتاب بيختبركم +اختبار على مهارات الباسكتبول و كلها سهله\n\nالبونس: فيه واجب بحث تسويه و يعطيك ثلاثة بوينتس +بطوله اذا حضرت تاخذ ٥ بوينتس\n\nالتقيم العام للمدرس : D+\n\nملاحظة:المدرس مشدد المادة مرة و مخليها كانها فيزكس او ماث +و دايم يقعد يتريق عالطلاب و يصارخ و يتنرفز من اسباب تافهه :busted_red: +يدقق على موضوع القريدات اذكر مرة جيته لان كان بيني و بين القريد الثاني درجة ولا رضا يعطيني نصيحة لوجه الله اذا انت منت رياضي و تبي قريد بدون تعب و مدرس فلكسبل اشرد منه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1496193-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/62", "user": "Bader_Alqahtani", "ts": 1532261642000, "tid": 80975, "pn": 62}}]}', 1532261642000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-khdsa2022-pe101', 'stk-khdsa2022', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATS APP\nاسم الدكتور : حبيب الربيعان\nالمادة: PE 101\nالفصل الدراسي: 191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : بعد ٥ دقايق يبدا التحضير\nطريقة الشرح : يشرح لك المهاره ويخليك تتدرب\nالكويزات : كانت ١٠ اسئله تقريبًا وسهله من الكتاب واذا ما ذاكرت بتجيب ٧\nالمياجر: مافيه\nالفاينلات : مافيه\nالقريد النهائي: A+\nالصوت: واضح\nإضافات : الدكتور ططيب مره ومزوح ويعطي بونصات كثير لاتفرط فيها واحضر عنده لاتغيب وبتاخذ A+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518793-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/66", "user": "Khdsa2022", "ts": 1578285640000, "tid": 80975, "pn": 66}}, {"id": "stk-dr-f179144", "n": "Dr. Philip Watkins", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "BY WHATS APP\nاسم الدكتور : فلب\nالمادة: PE 101\nالفصل الدراسي:191\nبنود التقييم ⬇️⬇️⬇️\n\nالتحضير : بداية الكلاس وان تأخرت ثاتيك ليت\nطريقة الشرح : ماتفهم شي والوضع تسليك\nالكويزات : ما يغيرهم من الاوريا وعلى البلاك بورد\nالمياجر:…\nالفاينلات :…\nالقريد النهائي: B+\nالصوت: الاكسنت تبع برتش قوي فا صعب تفهم منه\nإضافات : بالنسبة لي اخذت A+ لاني كنت اصلا معضل وراعي جم اما الشباب الباقي 80٪ يذموه\nطبعا فلبلاتغيب معاه وبين انك تتمرن في الجم واضمن A+ في المخبى\n>>>>>>>>>>>>>>>>>>>>>> اللي كتب التقييم معضل مو اللي نقله للمنتدى 😀", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518840-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/philip-watkins/179144/8", "user": "Khdsa2022", "ts": 1578295292000, "tid": 179144, "pn": 8}}]}', 1578285640000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-iiahmadx-pe101', 'stk-iiahmadx', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80975", "n": "Dr. Habeeb Al-Raban", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "الدكتور/ حبيب الربيعان\nT212 - PE101- Basketball\n\nالتحضير\n:\nبداية الكلاس ويسمح بالتأخير البسيط في حال كلاسك الي قبل بعيد, ولكن بشرط تكلمه قبلها… + يسمح بحضور كلاس بوقت ثاني ولكن لازم تكلمه. ولكن اي تأخير بدون ما تقله بيخصم عليك مباشرةً, طبعا كان فيه غياب واحد مجاني فقط لا غير.\n\nطريقة الشرح\n:\nالدكتور يشرح الاساسيات بشكل تفاعلي بحيث تترسخ بعقل الطالب ولا يضطر يراجع او يذاكر شيء, طبعا الكورس جزء نظري وجزء عملي… بالعملي يشرح الموضوع وبعدها يخليكم تلعبون قيم ضد بعض وتطبقون الي تعلمتوه, وعلى كذا… بالنسبه للنظري سلايدات ويقرا وصلى الله وبارك.\n\nالكويزات\n:\nسهلة الى حد ما, اذا ذاكرت زين بتجيب فل بالراحه, الكويزات النظرية كان يجي فيها سؤال واحد بس صعب اما الباقي تافه…\n\nالفاينل\n:\nكان عباره عن دربل بالكورة حول اقماع وبعدها تسجل شوته من اختياره “نوع”… كان للأمانه متساهل بالذات مع السمينين, ولكن مو اي احد طبعا! انت سو الي عليك واذا شافك تتعب وكذا م بيقصر معك وهذا الي شفته للأمانه.\n\nالصوت\n: ممتاز وواضح ولكن اللغة فيها تكسير بسيط.\nالقريد النهائي: +A\n\nإضافات :\nنزل عنده اذا لقيته, احياناً يكنسل كلاسات ولكن يعلم قبلها + البونص عنده جيد… تقريبا زودني 5 درجات فوق ما استحق, ويعطي الطالب قد جهده .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535184-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/habeeb-al-raban/80975/70", "user": "IIAhmaDx", "ts": 1661459210000, "tid": 80975, "pn": 70}}]}', 1661459210000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mr.sir-pe101', 'stk-mr.sir', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f80987", "n": "Dr. A Vargees", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "منزل عنده هذا الترم 151 Pe 101\nطيب وحبوب عادي تجيه بأي سكشن غير سكشنك\nغبت ع الاختبار حق الكتاب وسمح لي اعيده مع انه ماكان عندي عذر\nباختصار كتعامل واخلاق ممتاز\nقريدات مدري الله يستر:D", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1431952-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/a-vargees/80987/19", "user": "MR.Sir", "ts": 1446548594000, "tid": 80987, "pn": 19}}]}', 1446548594000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user8581-pe101', 'stk-user8581', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f90478", "n": "Dr. Rakesh Tomar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "term131\nbadminton pe101\nماهو شديد بالتحضير اذا جيت متأخر خمس دقايق او اقل يحضرك عادي … يسمح بالميك اب على حسب …مثلا اول الاسابيع واخر اسبوعين الي مافيهم لعب يسمح بالميك اب …لكن بقية السمستر مستحيل .\n\nالكويزات\nكنا مع طلاب الربعان فما ادري اهو الي كتاب الاسئلة او الربعان لكن كان سهل: اختيارات وصح وخطأ .\n\nتقسيم الدرجات كان كذا\n10 اختبار إرسال\n10 اختبار لقوانين اللعبة ( خلاه بونص لكل الطلاب )\n50 درجة على المباريات الي راح تكون بين الطلاب ويقسم الدرجات على حسب أفضل واحد أو اثنين في المباريات\nبقية الدرجات على الحضور والفتنس تست …\n\nمحترم وطيب جدا ومتعاون مع الطلاب لكن لاتغيب عنده كثير لأنه راح ياخذ فكرة عنك\nوفي الدرجات اشوفه ممتاز وبحسب الي درسوا معاه قبل في آخر كلاس يعطيك قريد واذا شيكت على البورتال تشوف معطيك قريد اعلى … + سهل تاخذ عنده a+\nاهم شي سو الي يبيه وحاول تفوز في اغلب المباريات في الـ badminton انا خسرت 6 مباريات واعطاني a+", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1316056-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakesh-tomar/90478/28", "user": "user8581", "ts": 1389010752000, "tid": 90478, "pn": 28}}]}', 1389010752000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-silver2012-pe101', 'stk-silver2012', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f90478", "n": "Dr. Rakesh Tomar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "السمستر 132 , المادة pe101 ريشة\nالتحضير :يحضر يوميا ولايمكن ينسى , يحجر بالميك أب شوي , احيانا اذا جيت متأخر ويحطك غايب وماينتبه لك انك جاي متأخر فتتفاجأ نهاية السمستر بكثرة غياباتك لذلك شيك غياباتك وياه اول بأول , اغلب مدرسين البي اي يخصم 3 درجات لكل غياب , بس راكيش تومار مايمشي ع هالقاعدة .\nطريقة الشرح :بالفزكال اديوكيشن بوك يكون الشرح بربره وسواليف بس شرح محترم ويوصل لك المعلومة , اثناء ممارسة اللعبة يعطيك قواعد بيسك يشرحها مرة واحدة ويحاسبك عليها بالاختبار النهائي حق اللعبة\n\nالكويزات : مافيه كويزات بالبي اي\nالمياجر: بالفزكال اديوكيشن تست عطانا ورقة فيها 20 جمله تحفظها كاملة ويجي الاختبار ترو اند فالس على عشر جمل مختارة من ضمن الجمل اللي بالورقة\nالفاينلات :_\nالقريد النهائي:a\nالصوت:واضح جدا وانجليزيته واضحه على الرغم من ان بعض الكلمات لايستطيع نطقها بشكل صحيح نظرا لهندية لسانه\nإضافات :\nالمدرس عصبي , بس بالنهاية اغلب الكلاس بي وبي بلس والقليل من ايه وايه بلس , كان يمشينا بدري جدا قبل نهاية الكلاس بعشرين دقيقة .\n\nتنبيه :\nتعامله مع الاوريا مختلف تماما عن اللي ذكرته حيث انه يطالبهم ببرزنتيشن من كتاب الفزكال اديوكيشن ويشدد على الغيابات اكثر بالاوريا .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1373426-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakesh-tomar/90478/34", "user": "silver2012", "ts": 1401295597000, "tid": 90478, "pn": 34}}]}', 1401295597000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-deadly_scorpion-pe101', 'stk-deadly_scorpion', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f90478", "n": "Dr. Rakesh Tomar", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "(PE 101 (163\n\nالتحضير: ينادي عالارقام ويسمح بالتأخير لمدة 10 دقايق بس ميك اب لا\nالشرح: لما شرحلنا الكتاب كان شرحو مفهوم وتمام بس شرح الرياضة كان شوي متوتر وهو بشرح فبالعافية ممكن تفهم عليه\nالكويزات: كويز للكتاب وكان سهل والrules تبعت الرياضة كويز ثاني وكان اسهل\nالمياجر: NA\nالفاينلات: NA\nالقريد النهائي: A\nالصوت: صوتو مسموع ولهجتو شوية يمين شمال بس بفهم الواحد عليه\nاضافات: الدكتور اخلاقه ما شاء الله وطيب وبعطي بونصات بس مو ببلاش يعني لازم تفرجيه انك مهتم عشان البونص، كان يوعدنا انو ما حد ينزل عن A الا اكمن واحد وما ظلم احد بالدرجات عالعكس زود الكل ورفعهم", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1479128-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rakesh-tomar/90478/41", "user": "Deadly_Scorpion", "ts": 1503472200000, "tid": 90478, "pn": 41}}]}', 1503472200000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-m_shaer6-pe101', 'stk-m_shaer6', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f118779", "n": "Dr. Abdussalam Kanniyan", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "بنود التقييم :\nPE 101 - FOOTBALL\nPE 102 - VOLLYBALL\n\nالتحضير :\nتحضير بداية كل كلاس … وأتوقع انه يحاسب ع التأخير مو متأكد …\nطبعاً كل غياب بيخصم عليه مايمشي … ولا غالباً ما يرضى بالميك أب …\n\nطريقة الشرح :\nبداية السمستر شرح من سلايدات وينزلها لكم بالبلاك بورد …\n\nالكويزات :\nكوزاته صعبه صراحه … ويبي لها مذاكره كويسه …\nفيها اختياري وصح وخطأ واملأ الفراغ وتوصيل …\n\nالقريد النهائي:\nحول الـ B+ و الـA …\n\nالصوت:\nراح تفهم عليه … بس كلامه شويتين مضروب …\n\nإضافات :\nعنده هوموورك عليه بونس بوينتين …\nو اذا حضرت الكومبتشن يعطيك بونس … ولو مشارك بونس اكثر …\nيحاسب ع اختبار الفتنس واختبار المهارة …\nنهاية السمستر راح يقول لك درجتك الي جبتها (احتامل تحسه ظلمك فيها) … وبعدين يزيدها شوي …\nيعني يمكن يعطيك حقك لا اكثر ولا اقل … و يمكن يزيدك شوي …\nو تراه آخر دكتور ينزل القريدات … راح تتعب وانت تنتظره …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1473991-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/abdussalam-kanniyan/118779/12", "user": "m_shaer6", "ts": 1495990732000, "tid": 118779, "pn": 12}}]}', 1495990732000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-moh_ammed-pe101', 'stk-moh_ammed', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f148177", "n": "Dr. Ertan Tufekcio", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 (Term 202 - online)\nالتحضير: يخلينا نرفع أيادينا أو يسأل سؤال وتجاوب في الشات…الزبدة مافيه طريقة ثابتة للتحضير.\n\nالصوت: لهجته تركية لاباس فيها.\n\nالكويزات: مستواها من سهل إلى متوسط، غالبا تكفيك القراءة عشان تجيب الدرجة كاملة أو قريب من الكاملة.\n\nإضافات: -غالب الترم كان يخلينا نفتح الكاميرات ونسوي تمارين قدامه (ما أدري إذا كل المدرسين كذا ولا لا).\n-الدكتور عطانا مهام تعجيزية ، مثال: طلب منا إنك تمشي 10 آلاف خطوة يوميا لمدة شهر !! .\n-للأسف كان فيه غش كثييير، وأظن 99% من الطلاب أو أكثر غشوا سواء في الكويزات أو في المهام الأخرى مثل مهمة المشي اللي ذكرتها (كانوا يستخدمون برامج أو شيء من هذا القبيل عشان يغيرون عدد الخطوات).\nللأمانة إني سلمت للدكتور عدد خطوات أقل بكثيير جدا عن اللي طلبه (أقل من 10%) ولكنه عطاني أكثر من نص الدرجة على ما أذكر.\n\nبصراحة أنا ما أدري عن النظام عند بقية المدرسين، ولكن إذا كان نظامهم مختلف عن كذا فأنصحك ماتنزل عند هالدكتور وتروح لواحد غيره لأن المادة بتتحول من إنها مادة للطقطقة إلى مادة غثيثة جدا.\n\nالقريد النهائي: D", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1530294-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ertan-tufekcio/148177/20", "user": "Moh_ammed", "ts": 1622651780000, "tid": 148177, "pn": 20}}]}', 1622651780000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_aldoseri-pe101', 'stk-mohammed_aldoseri', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f148177", "n": "Dr. Ertan Tufekcio", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 - Term 211\n\nالتحضير :\nفي بداية الترم كان يحضّر في بداية الكلاس وبعدين صار التحضير في آخر الكلاس. يسمح بالميك أب ولو جيت متأخر في الغالب بيمشّيها.\n\nطريقة الشرح :\nالمادة ما تحتاج لشرح أصلا ولكن كان يشرحها بأسلوب حلو وكان يتكلم دايم بمواضيع نفسية وصحية بشكل بسيط ومفهوم.\n\nالكويزات :\nلا يوجد\n\nالمياجر:\nالاختبارات النظرية عنده كان مستواها متوسط والإختبارات العملية اذا بديت تتمرن معه من البداية مراح يكون صعب عليك الاختبار العملي.\n\nالفاينلات :\nلا يوجد\n\nالقريد النهائي:\nA+\n\nالصوت:\nواضح ولهجته أوروبية مفهومة.\n\nالبونص:\nالبونص كان على متوسط عدد الخطوات في شهرين واذا كنت تحضر كلاساته بسيكل أيضا لك بونص عنده.\n\nإضافات :\nالدكتور أخلاقه جميلة ومتواضع جدا وما قد طلبت منه حاجة ورفض, والكلاس عنده كان خفيف وفيه ضحك وطقطقة, ومن وقت لوقت كنا نلعب معه كورة خارج الدوام.\nبشكل عام الدكتور ممتاز واذا يناسبك وقت كلاساته لا يفوتك.\n\nتنويه : التقييم في كلاسات الأونلاين ممكن يفرق عن الحضوري , وتجربتي مع الدكتور كانت حضوريا.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1533453-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/ertan-tufekcio/148177/21", "user": "Mohammed_Aldoseri", "ts": 1642129687000, "tid": 148177, "pn": 21}}]}', 1642129687000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mj77-pe101', 'stk-mj77', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f175801", "n": "Dr. Martin Pacholek", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Pe 101 basketball\n\nالتحضير : معاك لين 10 دقايق بعدها مايدخلك\nطريقة الشرح : يشرح من السلايدات وشرح ممتاز\n\nالكويزات : اختبار واحد يكون اللي هو الفاينل ويكون من ١٠ اسئله اختيارات بس تختار كل الاختيارات لو الاختيارات صحيحه\nالمياجر: -\nالفاينلات : -\nالقريد النهائي: A\nالصوت: ممتاز\nإضافات : الدكتور اخلاق جداً وبونصه كثير بعد ، كيف تاخذ البونص ؟ يسوي تحديات باللعب واول تيم او اول شخص يسويه يعطيه البونص ، الدكتور كريييف اللي يبي الراحه يبعد عنه . صار لي مشكله معاه خسفني في تقييم الاسكلز ورحت وكلمته وقال بصورك فديو عشان تشوف اخطائك قلت تمام وصورني وانا اسوي الاختبار وبعدها جلس يطالع ويصرف ويقول هنا غلطت وانا ماغلطت بعدها قلت له خلاص سويي اللي تبيه اذا تشوف اني استحق ذي الدرجه ولحقني واعتذر وقال لي بعيد لك الاختبار وعدته والحمدلله انصفني", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504134-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/martin-pacholek/175801/7", "user": "mj77", "ts": 1545882046000, "tid": 175801, "pn": 7}}]}', 1545882046000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rapls-pe101', 'stk-rapls', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f175801", "n": "Dr. Martin Pacholek", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 - Badminton\n\nالتحضير : بعد عشر دقايق يقولك تعال مع الكلاس الثاني .\n\nطريقة الشرح : يشرح الكتاب من سلايدات عنده , شرحه ممتاز , يقول اللي يبي يشرح احد الدروس يسوي عرض هو ومجموعته ولهم بونص لكن مو اجباري , يعلق بعد كل عرض تعليقات ع الدرس , ويشرح الدروس اللل\n\nالكويزات : على كلامه ان اختباره لطلاب الاوريا خيارات اوجد الاجابة الصحيحة , لكن للفرشمن اوجد ( جميع ) الاجوبة الصحيحة , وهذا اللي صعب اختبارنا وصار يحتاج مذاكرة .\n\nالمياجر: -\n\nالفاينلات : -\n\nالقريد النهائي: A+\n\nالصوت: واضح وممتاز , والاكسنت مفهوم .\n\nإضافات : الدكتور متعاون ويحب يساعد الطالب , لكن يبي الطالب يتعاون معاه برضو , يمكن البعض يشوفه يكرف لكنه يعطي كل طالب اللي يستاهل وما يظلم , يعطي بونصات كثير في كل كلاس تقريبًا , ما يعطي ابقريد لكن لطبيعة لعبة كرة الريشة ف كان البونص عندنا أقل من طلابه في كرة السلة , ف قال سكاشن الريشة لهم ابقريد من درجة , اخر السمستر يسمح باعادة اختبار السكلز والاختبار التحريري , يسوي انشطة خارجية كل جمعة , مثلًا لعب كرة قدم وزي كذا .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1504746-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/martin-pacholek/175801/8", "user": "Rapls", "ts": 1547042943000, "tid": 175801, "pn": 8}}]}', 1547042943000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-tsonayoshi-pe101', 'stk-tsonayoshi', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f175801", "n": "Dr. Martin Pacholek", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101 - 191 كرة قدم\n\nالتحضير : اسطوري عندك 10 دقايق تتاخر فيها بعدين احضر مع كلاس ثاني ، يمديك تسوي ميك اب اي وقت تبغى مو لازم تكلمه قبل لا تسوي ، يحضر بداية الكلاس\n\nطريقة الشرح : نبدأ بالتحمية بعدين حصة يشرح فيها المهارة ونطبقها والحصة اللي بعدها نلعب مباراة نطبق فيها المهارة والجزء النظري شرحه ممتاز ويمديك تشرح درس وتاخذ بونص\n\nالكويزات : لا يوجد\n\nالمياجر: لا يوجد\n\nالفاينلات : فاينل الجزء العملي ماحد نقص اكثر من 5 درجات ، اما الجزء النظري يحتاج مذاكرة الاختبار يكون خيارات اختار كل الاجابات الصحيحة للسؤال ممكن كلهم ممكن وحدة بس فلازم تذاكرله ويمديك تعيده نهاية الفصل اذا ما عجبتك الدرجة\n\nالقريد النهائي: A+\n\nالصوت: واضح واحيانا يقط كلمات عربية بلهجته الركيكه تلطف الجو\n\nإضافات : وقت تطبيق المهارة يسوي زي المسابقة واللي يفوز فيها ياخذ بونص", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1518461-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/martin-pacholek/175801/11", "user": "tsonayoshi", "ts": 1577695046000, "tid": 175801, "pn": 11}}]}', 1577695046000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-alhussain_bin_alshei-pe101', 'stk-alhussain_bin_alshei', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f175801", "n": "Dr. Martin Pacholek", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE101\nالترم: 201 ( درسنا الترم كامل أون لاين )\n\nالتحضير: التحضير في بداية الحصة غالبا بس بعض الأحيان يحضر في الأخير وطريقته في التحضير ان كل واحد يقول رقمه الي عطاه اياه يعني رقم واحد يقول واحد تالي بعده رقم اثنين يقول اثنين بعده رقم ثلاثة يقول ثلاثة وهكذا والي ما رد من اول مرة يردد اسمائهم مرة ثانية عشان يتأكد. 👍\n\nالشرح: في الجزء النظري, حق الأمراض السكري وانخفاض الضغط وغيره, قسمنا إلى مجموعات يعطي كل مجموعة موضوع وبعد خمس إلى عشر دقايق نقرا ونبحث عن هالموضوع في جوجل او في الكتاب و بعدها كل مجموعة تشرح موضوعها وافضل مجموعة تشرح بعض الأحيان يعطيها بونص ويعطي مجموعة فيهم تضع اسالة عن الدرس والي يجاوبها له بونص. اما في الجزء العلمي فخلانا نستعمل تطبيق اسمه Runkeeper.\n\nالكوزات: كوزاته سهلة بس أقرأ الماتيريال الي يحدده وانشاء الله امورك طيبة.\nالمياجر:-\nالفاينل:-\nالصوت: لهجة أوروبية تشيكية. بعض الأحيان ما تفهم شيقول بس اغلب كلامه واضح.\nفاينل قريد : A+\n\nإضافات: الدكتور ذه يحب يكرف الطلاب بدنيا فأذا كنت من النوع الكسول الي ما يبي يتحرك يمكن ما يصلح لك. دائما يبي يوصل فكرة ان الرياضة اسلوب حياة وليست كورس تنزله تتمرن شويتين وخلاص فهو يحاول يغرس ثقافة ممارسة الرياضة في طلابه وانا الصراحة احترمه كثيرا بسبب هذا الشيء. يعطي فرص للبونص كثيرة يمكن تقريبا حصلت عنده اكثر من 4 بونصات. طيب جدا و خلوق ومعضل 😏", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1527712-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/martin-pacholek/175801/15", "user": "Alhussain_Bin_Alshei", "ts": 1610163950000, "tid": 175801, "pn": 15}}]}', 1610163950000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12137-pe101', 'stk-user12137', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f176973", "n": "Dr. Erdogan Tabur", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "PE 101- TERM 221\nالتحضير : نهاية كل كلاس\nطريقة الشرح : نهاية الترم يشرح وكلها كم حصة يشرح نفس الي درسناه بالتحضيري ملل كان , اما بالعملي كان يروينا التمارين الي نسويها بشكل واضح\nالكويزات : سهلة ومذاكرتها سريعة ما اعطانا الا كويز واحد\nالقريد النهائي: C+\nالصوت: واضح جدا\nإضافات : مشكلته ما كان يرضى بالميكب اب وغير كذا التمارين للاروبيك مضروبة يخليك تمسح الارض بس متساهل ويحب ينكت ويسولف", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536216-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/erdogan-tabur/176973/8", "user": "user12137", "ts": 1674222643000, "tid": 176973, "pn": 8}}]}', 1674222643000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mashal_35-pe101', 'stk-mashal_35', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f179144", "n": "Dr. Philip Watkins", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "مبالغ فيه كلامك … انا خذيت PE101 و جبت عنده A+ الحمدلله ، الدكتور متعاون و يرفع الطلاب بالدرجات ( ٤ درجات بونص اذا ما عندك غياب و اذا غياب يخصم درجتين و اذا غيابين يخصم ٤ درجات يعني طار البونص بس بفايدة ) و الي يجيب ٩٤ يدفه درجة عشان الA+ الدكتور كريف تمارين بس يدف بالدرجات .", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1498560-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/philip-watkins/179144/3", "user": "Mashal_35", "ts": 1535804520000, "tid": 179144, "pn": 3}}]}', 1535804520000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-abdullah_n1-pe101', 'stk-abdullah_n1', 'PE 101', 'doc', '{"docs": [{"id": "stk-dr-f179144", "n": "Dr. Philip Watkins", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "اسم الدكتور : فلب واتكنس\nالمادة: PE 101\nالفصل الدراسي: 191\n\nالتحضير : شديد بالتحضير كنك بالعسكرية\nالقريد النهائي: F- وكثيرة عليه\nالصوت: لهجته صعبة تنفهم ويستخدم كلمات صعبة جداً لناس ماهم native كذا بس عشان يستلعن على الطلاب\nإضافات : الدكتور ذا نذل بالدرجات كان باقي لي درجة وحدة على الـ A وما زودني مع انه كرفنا كرف الموت وما غبت عنده ولا غياب\nوخلنا نسوي جداول تمرين واختباره كان اختبار طلاب طب بالأخير القريدات سيئة للكلاس كامل!\nفر فرار الأسد ولا تسجل عنده، بتندم على كل لحضة بذاك الكلاس!", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1525208-pe101", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/philip-watkins/179144/10", "user": "Abdullah_N1", "ts": 1598705397000, "tid": 179144, "pn": 10}}]}', 1598705397000, 1794828446, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
